From a71e891e539d2a11f45f3304908a2ee2eb89f7fd Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 15:09:02 +0100
Subject: [PATCH] desktoppackage/logout: Keep the controls on the screen with
 keyboard focus

With several screens the controls stayed on the first screen while the
keyboard went to another screen's window, so arrow keys moved an unseen
highlight. Now the controls move to whichever screen's window is active.

BUG: 390503
---
 desktoppackage/contents/logout/Logout.qml | 18 +++++++++++++++---
 1 file changed, 15 insertions(+), 3 deletions(-)

diff --git a/desktoppackage/contents/logout/Logout.qml b/desktoppackage/contents/logout/Logout.qml
index 35f7ea6345..1f0b554f2c 100644
--- a/desktoppackage/contents/logout/Logout.qml
+++ b/desktoppackage/contents/logout/Logout.qml
@@ -65,8 +65,22 @@ Item {
         }
     }

+    function takeControls() {
+        if (ControlsOwner.controls && ControlsOwner.controls.parent !== root) {
+            ControlsOwner.controls.parent = root;
+        }
+    }
+
     Component.onCompleted: ensureControlsExist()

+    // The keyboard goes to whichever screen's window is active, so keep the
+    // controls (and their focus highlight) on that screen.
+    Window.onActiveChanged: {
+        if (Window.active) {
+            takeControls();
+        }
+    }
+
     // Not MouseArea: hovering a LogoutButton steals
     // the pointer from it, so containsMouse would flicker and the row would
     // flash in and out. HoverHandler is non-blocking, so it just tracks the
@@ -77,9 +91,7 @@ Item {
                 if (root.Window.window) {
                     root.Window.window.requestActivate();
                 }
-                if (ControlsOwner.controls && ControlsOwner.controls.parent !== root) {
-                    ControlsOwner.controls.parent = root;
-                }
+                root.takeControls();
             }
         }
     }
-- 
